using System.Diagnostics.CodeAnalysis;
// ReSharper disable CommentTypo
// ReSharper disable IdentifierTypo

namespace MathCore.WPF.pInvoke;

/// <summary>Сообщения Windows</summary>
[SuppressMessage("ReSharper", "InconsistentNaming"), SuppressMessage("ReSharper", "UnusedMember.Global")]
internal enum WM : uint
{
    /// <summary>Сообщение WM_NULL не выполняет никаких действий, приложение отправляет его, если хочет опубликовать сообщение, которое окно-получатель проигнорирует</summary>
    NULL = 0x0000,
    /// <summary>Сообщение WM_CREATE отправляется, когда приложение запрашивает создание окна вызовом функций CreateWindowEx или CreateWindow, сообщение отправляется до возврата из функции, процедура окна нового окна получает это сообщение после создания окна, но до того, как окно станет видимым</summary>
    CREATE = 0x0001,
    /// <summary>
    /// Сообщение WM_DESTROY отправляется, когда окно уничтожается, оно отправляется процедуре окна уничтожаемого окна после удаления окна с экрана
    /// Это сообщение сначала отправляется уничтожаемому окну, затем дочерним окнам (если они есть) по мере их уничтожения
    /// Во время обработки сообщения можно считать, что все дочерние окна ещё существуют
    /// </summary>
    DESTROY = 0x0002,
    /// <summary>Сообщение WM_MOVE отправляется после перемещения окна</summary>
    MOVE = 0x0003,
    /// <summary>Сообщение WM_SIZE отправляется окну после изменения его размеров</summary>
    SIZE = 0x0005,
    /// <summary>Сообщение WM_ACTIVATE отправляется окну, которое активируется, и окну, которое деактивируется, при общей очереди ввода сообщение отправляется синхронно, сначала процедуре деактивируемого окна верхнего уровня, затем процедуре активируемого окна верхнего уровня, при разных очередях ввода сообщение отправляется асинхронно, и окно активируется немедленно</summary>
    ACTIVATE = 0x0006,
    /// <summary>Сообщение WM_SETFOCUS отправляется окну после получения фокуса клавиатуры</summary>
    SETFOCUS = 0x0007,
    /// <summary>Сообщение WM_KILLFOCUS отправляется окну непосредственно перед потерей фокуса клавиатуры</summary>
    KILLFOCUS = 0x0008,
    /// <summary>Сообщение WM_ENABLE отправляется, когда приложение изменяет состояние доступности окна, оно отправляется окну, чьё состояние изменяется, сообщение отправляется до возврата из функции EnableWindow, но после изменения стиля WS_DISABLED</summary>
    ENABLE = 0x000A,
    /// <summary>Сообщение WM_SETREDRAW позволяет разрешить или запретить перерисовку изменений в окне</summary>
    SETREDRAW = 0x000B,
    /// <summary>Сообщение WM_SETTEXT устанавливает текст окна</summary>
    SETTEXT = 0x000C,
    /// <summary>Сообщение WM_GETTEXT копирует текст окна в буфер, предоставленный вызывающим кодом</summary>
    GETTEXT = 0x000D,
    /// <summary>Сообщение WM_GETTEXTLENGTH определяет длину текста, связанного с окном, в символах</summary>
    GETTEXTLENGTH = 0x000E,
    /// <summary>Сообщение WM_PAINT отправляется, когда система или другое приложение запрашивает перерисовку части окна приложения, сообщение отправляется при вызове UpdateWindow или RedrawWindow, либо при обработке WM_PAINT, полученного через GetMessage или PeekMessage</summary>
    PAINT = 0x000F,
    /// <summary>Сообщение WM_CLOSE отправляется как сигнал о завершении окна или приложения</summary>
    CLOSE = 0x0010,
    /// <summary>
    /// Сообщение WM_QUERYENDSESSION отправляется, когда пользователь выбирает завершение сеанса или приложение вызывает одну из функций завершения работы системы
    /// Если какое-либо приложение возвращает ноль, сеанс не завершается, система прекращает отправку WM_QUERYENDSESSION, как только одно приложение возвращает ноль
    /// После обработки этого сообщения система отправляет WM_ENDSESSION с параметром wParam, равным результату WM_QUERYENDSESSION
    /// </summary>
    QUERYENDSESSION = 0x0011,
    /// <summary>Сообщение WM_QUERYOPEN отправляется значку, когда пользователь запрашивает восстановление окна до прежнего размера и положения</summary>
    QUERYOPEN = 0x0013,
    /// <summary>Сообщение WM_ENDSESSION отправляется приложению после обработки системой результатов WM_QUERYENDSESSION, оно сообщает приложению, завершается ли сеанс</summary>
    ENDSESSION = 0x0016,
    /// <summary>Сообщение WM_QUIT указывает на запрос завершения приложения и генерируется при вызове PostQuitMessage, оно приводит к возврату нуля из GetMessage</summary>
    QUIT = 0x0012,
    /// <summary>Сообщение WM_ERASEBKGND отправляется, когда фон окна должен быть очищен, например при изменении размеров, сообщение подготавливает недействительную часть окна к рисованию</summary>
    ERASEBKGND = 0x0014,
    /// <summary>Это сообщение отправляется всем окнам верхнего уровня при изменении системных цветов</summary>
    SYSCOLORCHANGE = 0x0015,
    /// <summary>Сообщение WM_SHOWWINDOW отправляется окну перед скрытием или показом</summary>
    SHOWWINDOW = 0x0018,
    /// <summary>
    /// Сообщение WM_WININICHANGE отправляется всем окнам верхнего уровня после изменения файла WIN.INI
    /// Функция SystemParametersInfo отправляет это сообщение после изменения параметра в WIN.INI
    /// Примечание: сообщение WM_WININICHANGE предоставляется только для совместимости с ранними версиями системы, приложениям следует использовать WM_SETTINGCHANGE
    /// </summary>
    WININICHANGE = 0x001A,
    /// <summary>
    /// Сообщение WM_WININICHANGE отправляется всем окнам верхнего уровня после изменения файла WIN.INI
    /// Функция SystemParametersInfo отправляет это сообщение после изменения параметра в WIN.INI
    /// Примечание: сообщение WM_WININICHANGE предоставляется только для совместимости с ранними версиями системы, приложениям следует использовать WM_SETTINGCHANGE
    /// </summary>
    SETTINGCHANGE = WININICHANGE,
    /// <summary>Сообщение WM_DEVMODECHANGE отправляется всем окнам верхнего уровня при изменении параметров режима устройства</summary>
    DEVMODECHANGE = 0x001B,
    /// <summary>Сообщение WM_ACTIVATEAPP отправляется, когда окно другого приложения собирается стать активным, сообщение отправляется приложению активируемого окна и приложению деактивируемого окна</summary>
    ACTIVATEAPP = 0x001C,
    /// <summary>Сообщение WM_FONTCHANGE отправляется всем окнам верхнего уровня после изменения пула шрифтов</summary>
    FONTCHANGE = 0x001D,
    /// <summary>Сообщение отправляется при изменении системного времени</summary>
    TIMECHANGE = 0x001E,
    /// <summary>Сообщение WM_CANCELMODE отправляется для отмены режимов, например захвата мыши, система отправляет его активному окну при показе диалогового окна или окна сообщений, некоторые функции отправляют его явно указанному окну независимо от активности, например EnableWindow при отключении окна</summary>
    CANCELMODE = 0x001F,
    /// <summary>Сообщение WM_SETCURSOR отправляется окну, если мышь перемещает курсор в пределах окна и ввод мыши не захвачен</summary>
    SETCURSOR = 0x0020,
    /// <summary>Сообщение WM_MOUSEACTIVATE отправляется, когда курсор находится в неактивном окне и пользователь нажимает кнопку мыши, родительское окно получает это сообщение только если дочернее окно передаёт его в DefWindowProc</summary>
    MOUSEACTIVATE = 0x0021,
    /// <summary>Сообщение WM_CHILDACTIVATE отправляется дочернему окну, когда пользователь щёлкает по заголовку окна или когда окно активируется, перемещается или изменяет размер</summary>
    CHILDACTIVATE = 0x0022,
    /// <summary>Сообщение WM_QUEUESYNC отправляется приложением CBT для отделения сообщений пользовательского ввода от других сообщений, отправляемых через процедуру перехвата WH_JOURNALPLAYBACK</summary>
    QUEUESYNC = 0x0023,
    /// <summary>Сообщение WM_GETMINMAXINFO отправляется окну, когда размер или положение окна собираются измениться, приложение может использовать это сообщение для переопределения размеров и положения максимизации или минимального и максимального размера отслеживания</summary>
    GETMINMAXINFO = 0x0024,
    /// <summary>Windows NT 3.51 и более ранние: сообщение WM_PAINTICON отправляется минимизированному окну для рисования значка, это сообщение не отправляется в новых версиях Windows, кроме редких случаев, описанных в примечаниях</summary>
    PAINTICON = 0x0026,
    /// <summary>Windows NT 3.51 и более ранние: сообщение WM_ICONERASEBKGND отправляется минимизированному окну, когда фон значка должен быть заполнен перед рисованием значка, окно получает это сообщение только если для класса окна определён значок, иначе отправляется WM_ERASEBKGND, это сообщение не отправляется в новых версиях Windows</summary>
    ICONERASEBKGND = 0x0027,
    /// <summary>Сообщение WM_NEXTDLGCTL отправляется процедуре диалогового окна для установки фокуса клавиатуры на другую кнопку диалога</summary>
    NEXTDLGCTL = 0x0028,
    /// <summary>Сообщение WM_SPOOLERSTATUS отправляется диспетчером печати при добавлении или удалении задания из очереди печати</summary>
    SPOOLERSTATUS = 0x002A,
    /// <summary>Сообщение WM_DRAWITEM отправляется родительскому окну кнопки, комбинированного списка, списка или меню с пользовательской отрисовкой при изменении визуального аспекта элемента управления</summary>
    DRAWITEM = 0x002B,
    /// <summary>Сообщение WM_MEASUREITEM отправляется окну-владельцу комбинированного списка, списка, списка представлений или пункта меню при создании элемента управления или меню</summary>
    MEASUREITEM = 0x002C,
    /// <summary>Сообщение WM_DELETEITEM отправляется владельцу списка или комбинированного списка при уничтожении или удалении элементов посредством LB_DELETESTRING, LB_RESETCONTENT, CB_DELETESTRING или CB_RESETCONTENT, система отправляет WM_DELETEITEM для каждого удалённого элемента, если данные элемента не равны нулю</summary>
    DELETEITEM = 0x002D,
    /// <summary>Отправляется списком с флагом LBS_WANTKEYBOARDINPUT владельцу в ответ на WM_KEYDOWN</summary>
    VKEYTOITEM = 0x002E,
    /// <summary>Отправляется списком с флагом LBS_WANTKEYBOARDINPUT владельцу в ответ на WM_CHAR</summary>
    CHARTOITEM = 0x002F,
    /// <summary>Сообщение WM_SETFONT задаёт шрифт, используемый элементом управления при рисовании текста</summary>
    SETFONT = 0x0030,
    /// <summary>Сообщение WM_GETFONT запрашивает у элемента управления шрифт, которым он в данный момент рисует текст</summary>
    GETFONT = 0x0031,
    /// <summary>Сообщение WM_SETHOTKEY связывает горячую клавишу с окном, при нажатии горячей клавиши система активирует окно</summary>
    SETHOTKEY = 0x0032,
    /// <summary>Сообщение WM_GETHOTKEY определяет горячую клавишу, связанную с окном</summary>
    GETHOTKEY = 0x0033,
    /// <summary>Сообщение WM_QUERYDRAGICON отправляется минимизированному окну, когда пользователь начинает перетаскивание, но у окна нет определённого значка класса, приложение может вернуть дескриптор значка или курсора, который будет отображаться при перетаскивании</summary>
    QUERYDRAGICON = 0x0037,
    /// <summary>Система отправляет сообщение WM_COMPAREITEM для определения относительной позиции нового элемента в отсортированном списке комбинированного списка или списка с пользовательской отрисовкой, когда приложение добавляет новый элемент, система отправляет это сообщение владельцу элемента управления, созданного с CBS_SORT или LBS_SORT</summary>
    COMPAREITEM = 0x0039,
    /// <summary>
    /// Active Accessibility отправляет сообщение WM_GETOBJECT для получения сведений об объекте доступности, содержащемся в серверном приложении
    /// Приложения никогда не отправляют это сообщение напрямую, оно отправляется только Active Accessibility в ответ на вызовы AccessibleObjectFromPoint, AccessibleObjectFromEvent или AccessibleObjectFromWindow
    /// Серверные приложения обрабатывают это сообщение
    /// </summary>
    GETOBJECT = 0x003D,
    /// <summary>Сообщение WM_COMPACTING отправляется всем окнам верхнего уровня, когда система обнаруживает, что более 12,5 процента времени в интервале 30–60 секунд тратится на уплотнение памяти, что указывает на нехватку памяти</summary>
    COMPACTING = 0x0041,
    /// <summary>WM_COMMNOTIFY устарело для Win32-приложений</summary>
    [Obsolete("Obsolete for Win32-Based Applications")]
    COMMNOTIFY = 0x0044,
    /// <summary>Сообщение WM_WINDOWPOSCHANGING отправляется окну, размеры, положение или место в Z-порядке которого собираются измениться в результате вызова SetWindowPos или другой функции управления окнами</summary>
    WINDOWPOSCHANGING = 0x0046,
    /// <summary>Сообщение WM_WINDOWPOSCHANGED отправляется окну, размеры, положение или место в Z-порядке которого изменились в результате вызова SetWindowPos или другой функции управления окнами</summary>
    WINDOWPOSCHANGED = 0x0047,
    /// <summary>
    /// Уведомляет приложения о том, что система, обычно работающая от батареи, собирается перейти в режим приостановки
    /// Использование: POWERBROADCAST
    /// </summary>
    [Obsolete("Use: POWERBROADCAST")]
    POWER = 0x0048,
    /// <summary>Сообщение WM_COPYDATA отправляется приложением для передачи данных другому приложению</summary>
    COPYDATA = 0x004A,
    /// <summary>Сообщение WM_CANCELJOURNAL отправляется приложению, когда пользователь отменяет Journaling активности приложения, сообщение отправляется с дескриптором окна NULL</summary>
    CANCELJOURNAL = 0x004B,
    /// <summary>Отправляется элементом управления родительскому окну при наступлении события или при необходимости получить дополнительные сведения</summary>
    NOTIFY = 0x004E,
    /// <summary>Сообщение WM_INPUTLANGCHANGEREQUEST публикуется в окне с фокусом, когда пользователь выбирает новый язык ввода с помощью горячей клавиши или индикатора на панели задач, приложение может принять изменение, передав сообщение в DefWindowProc, или отклонить его, немедленно вернувшись</summary>
    INPUTLANGCHANGEREQUEST = 0x0050,
    /// <summary>Сообщение WM_INPUTLANGCHANGE отправляется верхнему затронутому окну после изменения языка ввода приложения, следует выполнить специфичные настройки приложения и передать сообщение в DefWindowProc, который передаст его дочерним окнам первого уровня, а те — своим дочерним окнам</summary>
    INPUTLANGCHANGE = 0x0051,
    /// <summary>Отправляется приложению, инициировавшему обучающую карточку Windows Help, сообщение информирует приложение о нажатии на авторизуемую кнопку, приложение инициирует карточку, указав команду HELP_TCARD при вызове WinHelp</summary>
    TCARD = 0x0052,
    /// <summary>Сообщение WM_HELP указывает, что пользователь нажал клавишу F1, если активное меню существует, WM_HELP отправляется окну, связанному с меню, иначе — окну с фокусом клавиатуры, при отсутствии фокуса — активному окну</summary>
    HELP = 0x0053,
    /// <summary>Сообщение WM_USERCHANGED отправляется всем окнам после входа или выхода пользователя, система обновляет пользовательские параметры и отправляет сообщение сразу после обновления</summary>
    USERCHANGED = 0x0054,
    /// <summary>Определяет, принимает ли окно ANSI или Unicode структуры в уведомлении WM_NOTIFY, сообщения WM_NOTIFYFORMAT отправляются от общего элемента управления родителю и от родителя общему элементу управления</summary>
    NOTIFYFORMAT = 0x0055,
    /// <summary>Сообщение WM_CONTEXTMENU уведомляет окно о щелчке правой кнопкой мыши в окне</summary>
    CONTEXTMENU = 0x007B,
    /// <summary>Сообщение WM_STYLECHANGING отправляется окну, когда функция SetWindowLong собирается изменить один или несколько стилей окна</summary>
    STYLECHANGING = 0x007C,
    /// <summary>Сообщение WM_STYLECHANGED отправляется окну после того, как функция SetWindowLong изменила один или несколько стилей окна</summary>
    STYLECHANGED = 0x007D,
    /// <summary>Сообщение WM_DISPLAYCHANGE отправляется всем окнам при изменении разрешения дисплея</summary>
    DISPLAYCHANGE = 0x007E,
    /// <summary>Сообщение WM_GETICON отправляется окну для получения дескриптора большого или малого значка, связанного с окном, большой значок отображается в диалоге ALT+TAB, малый — в заголовке окна</summary>
    GETICON = 0x007F,
    /// <summary>Сообщение WM_SETICON связывает новый большой или малый значок с окном, большой значок отображается в диалоге ALT+TAB, малый — в заголовке окна</summary>
    SETICON = 0x0080,
    /// <summary>Сообщение WM_NCCREATE отправляется перед WM_CREATE при создании окна</summary>
    NCCREATE = 0x0081,
    /// <summary>
    /// Сообщение WM_NCDESTROY информирует окно о разрушении неклиентской области, функция DestroyWindow отправляет WM_NCDESTROY после WM_DESTROY
    /// WM_DESTROY используется для освобождения выделенного объекта памяти, связанного с окном
    /// WM_NCDESTROY отправляется после уничтожения дочерних окон, в отличие от WM_DESTROY, которое отправляется до уничтожения дочерних окон
    /// </summary>
    NCDESTROY = 0x0082,
    /// <summary>Сообщение WM_NCCALCSIZE отправляется, когда необходимо вычислить размер и положение клиентской области окна, обработка сообщения позволяет приложению управлять содержимым клиентской области при изменении размера или положения окна</summary>
    NCCALCSIZE = 0x0083,
    /// <summary>Сообщение WM_NCHITTEST отправляется окну при перемещении курсора или при нажатии и отпускании кнопки мыши, если мышь не захвачена, сообщение отправляется окну под курсором, иначе — окну, захватившему мышь</summary>
    NCHITTEST = 0x0084,
    /// <summary>Сообщение WM_NCPAINT отправляется окну, когда требуется нарисовать рамку</summary>
    NCPAINT = 0x0085,
    /// <summary>Сообщение WM_NCACTIVATE отправляется окну, когда его неклиентская область должна отобразить активное или неактивное состояние</summary>
    NCACTIVATE = 0x0086,
    /// <summary>Сообщение WM_GETDLGCODE отправляется процедуре окна, связанного с элементом управления, по умолчанию система обрабатывает весь ввод клавиатуры в элемент управления, система интерпретирует некоторые виды ввода как клавиши навигации диалога, чтобы переопределить это поведение, элемент управления может ответить на WM_GETDLGCODE, указав, какие типы ввода он хочет обрабатывать сам</summary>
    GETDLGCODE = 0x0087,
    /// <summary>Сообщение WM_SYNCPAINT используется для синхронизации рисования, избегая связывания независимых потоков GUI</summary>
    SYNCPAINT = 0x0088,
    /// <summary>Сообщение WM_NCMOUSEMOVE публикуется, когда курсор перемещается в неклиентской области окна, сообщение публикуется окну, которое содержит курсор, если окно захватило мышь, сообщение не публикуется</summary>
    NCMOUSEMOVE = 0x00A0,
