    /// <summary>Последнее сообщение диапазона AFX</summary>
    AFXLAST = 0x037F,
    /// <summary>Первое сообщение диапазона PENWIN</summary>
    PENWINFIRST = 0x0380,
    /// <summary>Последнее сообщение диапазона PENWIN</summary>
    PENWINLAST = 0x038F,
    /// <summary>Константа WM_APP используется приложениями для определения частных сообщений, обычно в виде WM_APP+X, где X — целое значение</summary>
    APP = 0x8000,
    /// <summary>Константа WM_USER используется приложениями для определения частных сообщений для закрытых классов окон, обычно в виде WM_USER+X, где X — целое значение</summary>
    USER = 0x0400,

    /// <summary>Сообщение WM_CPL_LAUNCH отправляется приложением Windows Control Panel для запроса запуска приложения панели управления</summary>
    CPL_LAUNCH = USER + 0x1000,
    /// <summary>Сообщение WM_CPL_LAUNCHED отправляется, когда приложение панели управления, запущенное сообщением WM_CPL_LAUNCH, завершено, сообщение WM_CPL_LAUNCHED отправляется окну, заданному параметром wParam сообщения WM_CPL_LAUNCH, которое запустило приложение</summary>
    CPL_LAUNCHED = USER + 0x1001,
    /// <summary>WM_SYSTIMER — это известное, но всё ещё недокументированное сообщение, Windows использует WM_SYSTIMER для внутренних действий, таких как прокрутка</summary>
    SYSTIMER = 0x118,

    /// <summary>Состояние доступности изменилось</summary>
    HSHELL_ACCESSIBILITYSTATE = 11,
    /// <summary>Оболочка должна активировать своё главное окно</summary>
    HSHELL_ACTIVATESHELLWINDOW = 3,
    /// <summary>
    /// Пользователь завершил событие ввода, например нажал кнопку команды приложения на мыши или клавишу команды приложения на клавиатуре, а приложение не обработало WM_APPCOMMAND, сгенерированное этим вводом
    /// Если процедура оболочки обрабатывает WM_COMMAND, она не должна вызывать CallNextHookEx, см. раздел Return Value для дополнительной информации
    /// </summary>
    HSHELL_APPCOMMAND = 12,
    /// <summary>Окно минимизируется или максимизируется, системе нужны координаты прямоугольника минимизированного окна</summary>
    HSHELL_GETMINRECT = 5,
    /// <summary>Язык клавиатуры был изменён или загружена новая раскладка</summary>
    HSHELL_LANGUAGE = 8,
    /// <summary>Заголовок окна на панели задач был перерисован</summary>
    HSHELL_REDRAW = 6,
    /// <summary>Пользователь выбрал список задач, приложение оболочки, предоставляющее список задач, должно вернуть TRUE, чтобы предотвратить запуск списка задач Windows</summary>
    HSHELL_TASKMAN = 7,
    /// <summary>Создано окно верхнего уровня без владельца, окно существует, когда система вызывает этот перехват</summary>
    HSHELL_WINDOWCREATED = 1,
    /// <summary>Окно верхнего уровня без владельца собирается быть уничтожено, окно ещё существует, когда система вызывает этот перехват</summary>
    HSHELL_WINDOWDESTROYED = 2,
    /// <summary>Активация изменилась на другое окно верхнего уровня без владельца</summary>
    HSHELL_WINDOWACTIVATED = 4,
    /// <summary>Окно верхнего уровня заменяется, окно существует, когда система вызывает этот перехват</summary>
    HSHELL_WINDOWREPLACED = 13
}